import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"60、【節】 兌下坎上","description":"周易尚氏學 - 60、【節】 兌下坎上","frontmatter":{"title":"60、【節】 兌下坎上","description":"周易尚氏學 - 60、【節】 兌下坎上"},"headers":[],"relativePath":"classics/shangshi/065.md","filePath":"classics/shangshi/065.md"}'),s={name:"classics/shangshi/065.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_60、【節】-兌下坎上" tabindex="-1">60、【節】 兌下坎上 <a class="header-anchor" href="#_60、【節】-兌下坎上" aria-label="Permalink to “60、【節】 兌下坎上”">​</a></h1><p>坎居西方。兌又居西。合為一處。故曰節。節信也。古剖竹為符。合以取信。故說文雲。節竹約也。序卦雲。物不可以終離。故受之以節。節之用在合。故與離對文。又曰節而信之。是序卦即以節為符信也。凡卦名皆從卦象生。震為竹。而二至五正反震。兩竹相合。則信成矣。而坎為信也。苦節向無通詁。虞翻命三變成離。火炎上作苦。以說苦節。而後儒多從之。誠以詁苦為甚為過。皆不安也。按周禮考工記。辨其苦良。史紀五帝紀。舜陶於河濱。器皆不苦窳。皆以苦為惡。節所以取信。苦窳則以持久。不能符合。故曰苦節不可貞。自先天象失傳。節字失詁。於是苦節之義。遂亦失矣。又坎為破。兌毀折。按卦象節易苦窳。戒之所以慎始也。</p><p>彖曰。節亨。剛柔分而剛得中。苦節不可貞。其道窮也。說以行險。當位以節。中正以通。天地節而四時成。節以制度。不傷財。不害民。</p><p>艮為道。又止故道窮。苟子性惡篇。故善言古者必有節於今。節信也。四時往來。不差不忒。故曰天地節而四時成。艮為時為成。震卦數四。故曰四時成。度丈尺也。度有制則民有信。信則不傷財。不害民。</p><p>象曰。澤上有水。節。君子以制數度。議德行。</p><p>數度皆所以取信於民。數紀於一。協於十。長於百。大於千。衍於萬。有數而度量衡以起。度十分為寸。十寸為尺。十尺為丈。而度之生由於律。律竹管也。累巨（左禾）黍九十為九寸。以為黃鐘之長。用以度長短。虞書雲。同律度量衡。誠以日久度量衡或差。同之以律。則不失毫釐。律者節也。人之德行。亦有定節。以取信於世。與數度同。故君子取以為法焉。</p><p>初九。不出戶庭。無咎。</p><p>初應在四。艮為戶庭。而二陽為阻。故不宜出。不出則無咎。象曰知通塞。言二阻寒也。</p><h3 id="象曰。不出戶庭。知通塞也。" tabindex="-1">象曰。不出戶庭。知通塞也。 <a class="header-anchor" href="#象曰。不出戶庭。知通塞也。" aria-label="Permalink to “象曰。不出戶庭。知通塞也。”">​</a></h3><p>初應在坎。坎為通。二遇敵。不能應四。故曰塞。知其塞不出戶庭。以求通。故曰知通塞。吳先生曰。易以陽在前為塞。陰在前為通。初之不出。以九二在前。故曰知通塞。二則可出而不出。故有失時之兇也。</p><p>九二。不出門庭。兇。</p><p>互艮為門庭。二比重陰。陽遇陰則通。通則利往。乃竟不出。是失時也。故兇。</p><h3 id="象曰。不出門庭兇。失時極也。" tabindex="-1">象曰。不出門庭兇。失時極也。 <a class="header-anchor" href="#象曰。不出門庭兇。失時極也。" aria-label="Permalink to “象曰。不出門庭兇。失時極也。”">​</a></h3><p>艮為時。極中也。說文極棟也。棟居屋脊。當屋之中。故極為中。失時極。即失時之中也。</p><p>六三。不節若。則嗟若。無咎。</p><p>三失位無應。故曰不節。震為笑。震反為艮則嗟矣。離九三雲。不鼓缶而歌。則大耋之嗟。與此象義並同也。王弼雲。若辭也。語助辭也。順二故無咎。</p><h3 id="象曰。不節之嗟。又誰咎也。" tabindex="-1">象曰。不節之嗟。又誰咎也。 <a class="header-anchor" href="#象曰。不節之嗟。又誰咎也。" aria-label="Permalink to “象曰。不節之嗟。又誰咎也。”">​</a></h3><p>言其咎在己。</p><p>六四。安節亨。</p><p>得位有應。上承九五。艮止為安。故安節亨。</p><h3 id="象曰。安節之亨。承上道也。" tabindex="-1">象曰。安節之亨。承上道也。 <a class="header-anchor" href="#象曰。安節之亨。承上道也。" aria-label="Permalink to “象曰。安節之亨。承上道也。”">​</a></h3><p>言能承上不失其道。</p><p>九五。甘節吉。往有尚。</p><p>說文。甘美也。美甘也。而坎為美脊。故坎有美象。甘節即美節也。節而美善。方可用以取信。與下苦節為對文。五當位居中。下乘重陰。正位居體。故甘節吉。爻在外為往。往得尊位。居之不疑。故曰往有尚。虞氏強命二變應五。以釋往字。豈知爻在外即曰往。泰否之大小往來可證也。</p><h3 id="象曰。甘節之吉。居位中也。" tabindex="-1">象曰。甘節之吉。居位中也。 <a class="header-anchor" href="#象曰。甘節之吉。居位中也。" aria-label="Permalink to “象曰。甘節之吉。居位中也。”">​</a></h3><p>艮為居。五中位。</p><p>上六。苦節貞兇。悔亡。</p><p>甘為美則苦為惡。坎為破。故曰苦節。節為信約。窳惡則不能符合。故貞兇。得位故無悔。</p><h3 id="象曰。若節貞兇。其道窮也" tabindex="-1">象曰。若節貞兇。其道窮也 <a class="header-anchor" href="#象曰。若節貞兇。其道窮也" aria-label="Permalink to “象曰。若節貞兇。其道窮也”">​</a></h3><p>在上無應故窮。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
